(** Positive binary-fold descent for core M until B1 or a right boundary. *)
From Coq Require Import Arith Lia List ZArith Bool.
From BBB4 Require Import BBB4_Statement BBBT4_Statement CTape.
From BBB4.Counters Require Import WTape NestCountTr LoopRunTr FiniteWallTr BinaryStackRankTr BlockCoreMReturnTr.
From BBB4.Checkers.IRules Require Import AnchorVisitsTr.
Import ListNotations.
Local Open Scope Z_scope.
Inductive bmf_tree(A:Type):nat->Type:=
| BMFLeaf:A->bmf_tree A 0
| BMFNode:forall n,bmf_tree A n->bmf_tree A n->bmf_tree A(S n).
Arguments BMFLeaf {A} _.
Arguments BMFNode {A n} _ _.
Fixpoint bmf_get{A n}(t:bmf_tree A n)(w:list Sym):A:=match t with
|BMFLeaf z=>z
|BMFNode a b=>match chd w with S0=>bmf_get a(ctl w)|S1=>bmf_get b(ctl w)end end.
Fixpoint bmf_pref(n:nat)(w:list Sym):list Sym:=match n with
|O=>[]|S k=>chd w::bmf_pref k(ctl w)end.
Lemma bmf_get_pref:forall A n(t:bmf_tree A n)m w,(n<=m)%nat->
 bmf_get t(bmf_pref m w)=bmf_get t w.
Proof.
 intros A n t;induction t as[z|n a IHa b IHb];intros m w H.
 - reflexivity.
 - destruct m;[lia|]. cbn[bmf_pref bmf_get chd ctl]. destruct(chd w);[apply IHa|apply IHb];lia.
Qed.
Definition bmf_allS(P:Sym->bool):bool:=P S0&&P S1.
Definition bmf_allQ(P:St->bool):bool:=P StA&&P StB&&P StC&&P StD.
Fixpoint bmf_allW(n:nat)(P:list Sym->bool):bool:=match n with
|O=>P[]|S k=>bmf_allS(fun a=>bmf_allW k(fun w=>P(a::w)))end.
Lemma bmf_allS_sound:forall P,bmf_allS P=true->forall a,P a=true.
Proof. intros P H[];unfold bmf_allS in H;apply andb_true_iff in H;tauto. Qed.
Lemma bmf_allQ_sound:forall P,bmf_allQ P=true->forall q,P q=true.
Proof. intros P H[];unfold bmf_allQ in H;repeat rewrite andb_true_iff in H;tauto. Qed.
Lemma bmf_allW_sound:forall n P,bmf_allW n P=true->forall w,length w=n->P w=true.
Proof.
 induction n as[|n IH];intros P H w HW.
 - destruct w;[exact H|discriminate].
 - destruct w as[|a w];[discriminate|]. cbn[length]in HW;injection HW as HW.
   cbn[bmf_allW]in H;pose proof(bmf_allS_sound _ H a)as Ha.
   exact(IH _ Ha w HW).
Qed.
Lemma bmf_pref_length:forall n w,length(bmf_pref n w)=n.
Proof. induction n;intro w;cbn[bmf_pref length];auto. Qed.
