Definition bmf_positive_check:=bmf_allQ(fun q=>bmf_allS(fun h=>
 bmf_allW 6(fun L=>bmf_allW 6(fun R=>
 if instr_eqb(q,h)(StB,S1)then true else
 Z.leb 0(bmf_vl L+bmf_vr R+bmf_bias(q,(L,h,R))))))).
Definition bmf_delta_check:=bmf_allQ(fun q=>bmf_allS(fun h=>
 bmf_allW 7(fun L=>bmf_allW 7(fun R=>
 let tr:=match bmf_tm q h with Some tr=>tr|None=>mkTrans S0 DL StA end in
 let d:=(t_next tr,ctape_move(t_dir tr)(t_write tr)(L,h,R))in
 if instr_eqb(q,h)(StB,S1)||instr_eqb(cinstr d)(StB,S1)then true else
 Z.ltb(bsr_delta bmf_fl bmf_fr bmf_bias(q,(L,h,R))tr)0)))).
Lemma bmf_fl_checked:bmf_fl_check=true.
Proof. vm_compute;reflexivity. Qed.
Lemma bmf_fr_checked:bmf_fr_check=true.
Proof. vm_compute;reflexivity. Qed.
Lemma bmf_positive_checked:bmf_positive_check=true.
Proof. vm_compute;reflexivity. Qed.
Lemma bmf_delta_checked:bmf_delta_check=true.
Proof. vm_compute;reflexivity. Qed.
